    private fun lodTooSmall(item:CachedGeometry):Boolean{val p=item.primitive;return when(p){is Primitive.Line->hypot(p.x2-p.x1,p.y2-p.y1)*scale<.9;is Primitive.Polyline,is Primitive.Face,is Primitive.Hatch->hypot((item.bounds.right-item.bounds.left).toDouble(),(item.bounds.top-item.bounds.bottom).toDouble())*scale<.9;is Primitive.Circle->p.radius*2*scale<.9;is Primitive.Arc->p.radius*2*scale<.9;is Primitive.Ellipse->hypot(p.ax,p.ay)*2*scale<.9;is Primitive.Point,is Primitive.Text->false}}
