    fun setLayerVisible(id:Int,visible:Boolean){if(id in visibleLayers.indices){visibleLayers[id]=visible;invalidate()}}
    fun setTextVisible(visible:Boolean){if(textVisible!=visible){textVisible=visible;invalidate()}}
    fun setMeasurementDecimalPlaces(decimalPlaces:Int){val normalized=decimalPlaces.coerceIn(0,4);if(measurementDecimalPlaces!=normalized){measurementDecimalPlaces=normalized;flexibleMeasurementFormat=measurementFormat(normalized,false);fixedMeasurementFormat=measurementFormat(normalized,true);emitOverlayState();invalidate()}}
    fun setMeasurementTextSize(sizeSp:Int){val normalized=sizeSp.coerceIn(12,24);if(measurementTextSizeSp!=normalized){measurementTextSizeSp=normalized;invalidate()}}
    fun setUseLayerColors(enabled:Boolean){if(useLayerColors!=enabled){useLayerColors=enabled;invalidate()}}
    fun setLayerColor(id:Int,color:Int?){if(id in layerColorOverrides.indices){layerColorOverrides[id]=color?.and(0xffffff)?:-1;invalidate()}}
    fun layerDisplayColor(id:Int):Int=resolvedLayerColor(id)
    fun isTextVisible()=textVisible
    fun isLayerVisible(id:Int)=visibleLayers.getOrElse(id){true}
    fun startMeasurement(){measuring=true;areaMode=false;coordinateMode=false;offsetMode=false;measureStart=null;measureEnd=null;pendingDistanceId=null;activeMeasurementColor=AREA_COLORS[overlays.count{it is DistanceOverlay}%AREA_COLORS.size];anySnapped=false;invalidate()}
    fun startArea(){measuring=true;areaMode=true;coordinateMode=false;offsetMode=false;measureStart=null;measureEnd=null;areaPoints.clear();activeMeasurementColor=AREA_COLORS[overlays.count{it is AreaOverlay}%AREA_COLORS.size];anySnapped=false;onAreaChanged?.invoke(0.0,model?.units?:DrawingUnit.UNKNOWN,0);invalidate()}
    fun startCoordinates(){measuring=true;areaMode=false;coordinateMode=true;offsetMode=false;measureStart=null;measureEnd=null;coordinatePoint=null;coordinateZ=null;invalidate()}
    fun startOffsetPoint(){measuring=true;areaMode=false;coordinateMode=false;offsetMode=true;offsetBase=null;offsetBaseZ=null;offsetPreview=null;invalidate()}
    fun startObjectSelection(){measuring=false;objectSelectionMode=true;selectedOverlayId=null;emitOverlayState();onObjectSelectionChanged?.invoke(null);invalidate()}
    fun stopObjectSelection(){objectSelectionMode=false;selectedObject=null;onObjectSelectionChanged?.invoke(null);invalidate()}
    fun setSelectedObjectColor(color:Int?){val selected=selectedObject?:return;if(color==null)objectColorOverrides.remove(selected)else objectColorOverrides[selected]=Color.rgb(Color.red(color),Color.green(color),Color.blue(color));emitObjectSelection();invalidate()}
    fun updateOffsetPreview(distance:Double?,angleDegrees:Double?){val base=offsetBase;if(base==null||distance==null||angleDegrees==null||!distance.isFinite()||!angleDegrees.isFinite()){offsetPreview=null;invalidate();return};val angle=Math.toRadians(angleDegrees);offsetPreview=Point2(base.x+distance*cos(angle),base.y+distance*sin(angle));invalidate()}
    fun createOffsetPoint(distance:Double,angleDegrees:Double):Point2?{val base=offsetBase?:return null;if(!distance.isFinite()||!angleDegrees.isFinite())return null;updateOffsetPreview(distance,angleDegrees);val point=offsetPreview?:return null;val overlay=CoordinateOverlay(nextOverlayId++,point,offsetBaseZ?:0.0,measurementAccentColor,coordinatePrimaryDefault);overlays+=overlay;selectedOverlayId=overlay.id;measuring=false;offsetMode=false;offsetBase=null;offsetBaseZ=null;offsetPreview=null;emitOverlayState();invalidate();return point}
    fun undoAreaPoint(){if(areaPoints.isNotEmpty())areaPoints.removeAt(if(areaDragIndex in areaPoints.indices)areaDragIndex else areaPoints.lastIndex);areaDragIndex=-1;notifyArea();invalidate()}
    fun clearArea(){areaPoints.clear();notifyArea();invalidate()}
    fun finishArea(){if(areaPoints.size>=3){overlays+=AreaOverlay(nextOverlayId++,areaPoints.toList(),activeMeasurementColor,areaPrimaryDefault,areaSecondaryDefault);notifyArea();emitOverlayState()};areaPoints.clear();areaDragIndex=-1;areaMode=false;measuring=false;invalidate()}
    fun finishMeasurement(){pendingDistanceId=null;selectedOverlayId=null;measuring=false;measureStart=null;measureEnd=null;emitOverlayState();invalidate()}
    fun cancelMeasurement(){pendingDistanceId?.let{id->overlays.removeAll{it.id==id};if(selectedOverlayId==id)selectedOverlayId=null};pendingDistanceId=null;if(coordinateMode&&coordinatePoint!=null){overlays+=CoordinateOverlay(nextOverlayId++,coordinatePoint!!,coordinateZ,measurementAccentColor,coordinatePrimaryDefault)};measuring=false;areaMode=false;coordinateMode=false;offsetMode=false;offsetBase=null;offsetBaseZ=null;offsetPreview=null;measureStart=null;measureEnd=null;coordinatePoint=null;coordinateZ=null;areaPoints.clear();emitOverlayState();invalidate()}
    fun toggleSelectedPrimary(){selectedOverlayId?.let{id->overlays.firstOrNull{it.id==id}}?.let{it.primaryVisible=!it.primaryVisible;when(it){is DistanceOverlay->distancePrimaryDefault=it.primaryVisible;is AreaOverlay->areaPrimaryDefault=it.primaryVisible;is CoordinateOverlay->coordinatePrimaryDefault=it.primaryVisible};emitOverlayState();invalidate()}}
    fun toggleSelectedSecondary(){selectedOverlayId?.let{id->overlays.firstOrNull{it.id==id}}?.let{if(overlayParts(it).second!=null){it.secondaryVisible=!it.secondaryVisible;when(it){is DistanceOverlay->distanceSecondaryDefault=it.secondaryVisible;is AreaOverlay->areaSecondaryDefault=it.secondaryVisible;is CoordinateOverlay->Unit}};emitOverlayState();invalidate()}}
    fun deleteSelectedOverlay(){val id=selectedOverlayId?:return;if(overlays.removeAll{it.id==id}){selectedOverlayId=null;emitOverlayState();invalidate()}}
    fun clearMeasurementOverlays(){if(overlays.isNotEmpty()){overlays.clear();selectedOverlayId=null;emitOverlayState();invalidate()}}
    fun fitToDrawing(){rotationDegrees=0f;fitPending=true;invalidate()}
    fun setRegressionViewport(stage:String){val rm=renderModel?:return;fit(rm.bounds);val factor=when(stage){"1.5x"->1.5f;"medium","2x"->2f;"close","4x"->4f;"8x"->8f;"16x"->16f;else->1f};if(factor!=1f){tx=width/2-(width/2-tx)*factor;ty=height/2-(height/2-ty)*factor;scale=(scale*factor).coerceIn(MIN_SCALE,MAX_SCALE)};diagnosticFramePending=true;Log.i(TAG,"viewportStage stage=$stage factor=$factor scale=$scale tx=$tx ty=$ty origin=${rm.originX},${rm.originY}");invalidate()}
