    fun setRegressionArea(enabled:Boolean){overlays.removeAll{it is AreaOverlay};if(enabled){val rm=renderModel?:return;val b=rm.bounds;val cx=rm.originX+(b.left+b.right)/2.0;val cy=rm.originY+(b.bottom+b.top)/2.0;val dx=(b.right-b.left)/8.0;val dy=(b.top-b.bottom)/8.0;overlays+=AreaOverlay(nextOverlayId++,listOf(Point2(cx-dx,cy-dy),Point2(cx+dx,cy-dy),Point2(cx,cy+dy)),AREA_COLORS[0])};emitOverlayState();Log.i(TAG,"regressionArea enabled=$enabled textColor=${textPaint.color}");invalidate()}
    fun setRegressionOverlays(command:String){val rm=renderModel?:return;when(command){"create"->{overlays.clear();val b=rm.bounds;val cx=rm.originX+(b.left+b.right)/2.0;val cy=rm.originY+(b.bottom+b.top)/2.0;val dx=(b.right-b.left)/10.0;val dy=(b.top-b.bottom)/10.0;overlays+=DistanceOverlay(nextOverlayId++,Point2(cx-dx,cy-dy),Point2(cx+dx,cy-dy),measurePaint.color);overlays+=AreaOverlay(nextOverlayId++,listOf(Point2(cx-dx,cy),Point2(cx,cy+dy),Point2(cx+dx,cy)),AREA_COLORS[0]);overlays+=AreaOverlay(nextOverlayId++,listOf(Point2(cx-dx,cy+dy*1.4),Point2(cx,cy+dy*2.2),Point2(cx+dx,cy+dy*1.4)),AREA_COLORS[1]);overlays+=CoordinateOverlay(nextOverlayId++,Point2(cx,cy-dy*2.0),null,measurePaint.color);selectedOverlayId=null};"delete_area"->{overlays.firstOrNull{it is AreaOverlay}?.let{overlays.remove(it)}};"delete_distance"->{overlays.firstOrNull{it is DistanceOverlay}?.let{overlays.remove(it)}};"clear"->overlays.clear()};if(overlays.none{it.id==selectedOverlayId})selectedOverlayId=null;emitOverlayState();Log.i(TAG,"regressionOverlays command=$command count=${overlays.size} distance=${overlays.count{it is DistanceOverlay}} area=${overlays.count{it is AreaOverlay}} coordinate=${overlays.count{it is CoordinateOverlay}}");invalidate()}
    fun startPerformanceStress(){if(stressFrame>=0)return;stressFrame=0;postOnAnimation(stressStep)}
    fun setPalette(background:Int,foreground:Int,accent:Int){if(backgroundColor==background&&foregroundColor==foreground&&measurementAccentColor==accent)return;backgroundColor=background;foregroundColor=foreground;measurementAccentColor=accent;paint.color=foreground;solidPaint.color=foreground;textPaint.color=foreground;measurePaint.color=accent;hatchPaint.color=foreground;hatchPaint.alpha=55;invalidate()}

    fun captureThumbnail(sizePx:Int=256):Bitmap?{
        if(sizePx<=0||width<=0||height<=0||renderModel==null)return null
        val sampleSize=sizePx*2
        val sample=Bitmap.createBitmap(sampleSize,sampleSize,Bitmap.Config.RGB_565)
        val sampleCanvas=Canvas(sample)
        val factor=max(sampleSize/width.toFloat(),sampleSize/height.toFloat())
        sampleCanvas.translate((sampleSize-width*factor)/2f,(sampleSize-height*factor)/2f)
        sampleCanvas.scale(factor,factor)
        draw(sampleCanvas)
        var left=sampleSize;var top=sampleSize;var right=-1;var bottom=-1
        val background=backgroundColor
        val bgR=Color.red(background);val bgG=Color.green(background);val bgB=Color.blue(background)
        val row=IntArray(sampleSize)
        for(y in 0 until sampleSize){
            sample.getPixels(row,0,sampleSize,0,y,sampleSize,1)
            for(x in row.indices){val color=row[x];val difference=abs(Color.red(color)-bgR)+abs(Color.green(color)-bgG)+abs(Color.blue(color)-bgB);if(difference>42){if(x<left)left=x;if(x>right)right=x;if(y<top)top=y;if(y>bottom)bottom=y}}
        }
        if(right<left||bottom<top)return sample
        val contentWidth=right-left+1;val contentHeight=bottom-top+1
        val padding=max(contentWidth,contentHeight)*.07f
        val side=(max(contentWidth,contentHeight)+padding*2).coerceAtMost(sampleSize.toFloat())
        val centerX=(left+right)/2f;val centerY=(top+bottom)/2f
        val srcLeft=(centerX-side/2).coerceIn(0f,sampleSize-side)
        val srcTop=(centerY-side/2).coerceIn(0f,sampleSize-side)
        val result=Bitmap.createBitmap(sizePx,sizePx,Bitmap.Config.RGB_565)
        Canvas(result).drawBitmap(sample,Rect(srcLeft.toInt(),srcTop.toInt(),(srcLeft+side).toInt(),(srcTop+side).toInt()),Rect(0,0,sizePx,sizePx),Paint(Paint.FILTER_BITMAP_FLAG))
        sample.recycle()
        return result
    }

    override fun onTouchEvent(e:MotionEvent):Boolean{detector.onTouchEvent(e);when(e.actionMasked){MotionEvent.ACTION_DOWN->{onCanvasTap?.invoke();lastX=e.x;lastY=e.y;moved=false;pinched=false;rotating=false;rotationActive=false;rotationLockedByZoom=false;areaDragIndex=if(areaMode)nearestAreaVertex(e.x,e.y)else-1};MotionEvent.ACTION_POINTER_DOWN->{pinched=true;moved=true;areaDragIndex=-1;if(e.pointerCount>=2){previousGestureAngle=gestureAngle(e);rotationStartAngle=previousGestureAngle;initialPinchSpan=hypot((e.getX(1)-e.getX(0)).toDouble(),(e.getY(1)-e.getY(0)).toDouble()).toFloat();rotating=true;rotationActive=false;rotationLockedByZoom=false}};MotionEvent.ACTION_MOVE->{if(e.pointerCount>=2)rotateGesture(e)else if(!detector.isInProgress){val dx=e.x-lastX;val dy=e.y-lastY;if(abs(dx)+abs(dy)>3)moved=true;if(areaMode&&areaDragIndex in areaPoints.indices){areaPoints[areaDragIndex]=screenPoint(e.x,e.y,true);notifyArea();invalidate()}else if(!measuring){tx+=dx;ty+=dy;invalidate()};lastX=e.x;lastY=e.y}};MotionEvent.ACTION_POINTER_UP->{pinched=true;moved=true;rotating=false;rotationActive=false;rotationLockedByZoom=false;areaDragIndex=-1;val remaining=if(e.actionIndex==0)1 else 0;if(remaining<e.pointerCount){lastX=e.getX(remaining);lastY=e.getY(remaining)}};MotionEvent.ACTION_UP->{if(!moved&&!pinched){if(measuring&&areaDragIndex<0)selectMeasurePoint(e.x,e.y)else if(objectSelectionMode)selectObjectAt(e.x,e.y)else if(!measuring)selectOverlayAt(e.x,e.y)};areaDragIndex=-1;pinched=false;rotating=false;rotationActive=false;rotationLockedByZoom=false};MotionEvent.ACTION_CANCEL->{moved=true;pinched=false;rotating=false;rotationActive=false;rotationLockedByZoom=false;areaDragIndex=-1}};return true}

    private fun gestureAngle(e:MotionEvent)=Math.toDegrees(atan2((e.getY(1)-e.getY(0)).toDouble(),(e.getX(1)-e.getX(0)).toDouble())).toFloat()
    private fun normalizedAngle(value:Float):Float{var result=value;while(result>180f)result-=360f;while(result<-180f)result+=360f;return result}
    private fun rotateGesture(e:MotionEvent){if(e.pointerCount<2||rotationLockedByZoom)return;val angle=gestureAngle(e);if(!rotating){previousGestureAngle=angle;rotationStartAngle=angle;rotating=true;rotationActive=false;return};var delta=normalizedAngle(angle-previousGestureAngle);previousGestureAngle=angle;if(!rotationActive){val total=normalizedAngle(angle-rotationStartAngle);if(abs(total)<ROTATION_SLOP_DEGREES)return;rotationActive=true;delta=total-sign(total)*ROTATION_SLOP_DEGREES};if(abs(delta)<.05f)return;val focusX=(e.getX(0)+e.getX(1))/2f;val focusY=(e.getY(0)+e.getY(1))/2f;val anchor=inverseLocal(focusX,focusY);rotationDegrees=(rotationDegrees+delta)%360f;placeLocalAt(anchor,focusX,focusY);pinched=true;moved=true;invalidate()}
    private fun inverseLocal(x:Float,y:Float):PointF{val radians=Math.toRadians(rotationDegrees.toDouble());val cosine=cos(radians).toFloat();val sine=sin(radians).toFloat();val dx=x-tx;val dy=y-ty;return PointF((cosine*dx+sine*dy)/scale,(-(-sine*dx+cosine*dy))/scale)}
    private fun placeLocalAt(local:PointF,x:Float,y:Float){val radians=Math.toRadians(rotationDegrees.toDouble());val cosine=cos(radians).toFloat();val sine=sin(radians).toFloat();val vx=local.x*scale;val vy=-local.y*scale;tx=x-(cosine*vx-sine*vy);ty=y-(sine*vx+cosine*vy)}
    private fun screenPosition(p:Point2):PointF{val rm=renderModel;val vx=(p.x-(rm?.originX?:0.0)).toFloat()*scale;val vy=-(p.y-(rm?.originY?:0.0)).toFloat()*scale;val radians=Math.toRadians(rotationDegrees.toDouble());val cosine=cos(radians).toFloat();val sine=sin(radians).toFloat();return PointF(tx+cosine*vx-sine*vy,ty+sine*vx+cosine*vy)}
    private fun nearestAreaVertex(x:Float,y:Float):Int{val limit=24f*resources.displayMetrics.density;var best=-1;var distance=limit*limit;for(i in areaPoints.indices){val screen=screenPosition(areaPoints[i]);val dx=screen.x-x;val dy=screen.y-y;val d=dx*dx+dy*dy;if(d<distance){distance=d;best=i}};return best}
    private fun screenPoint(x:Float,y:Float,snap:Boolean):Point2{val rm=renderModel;val local=inverseLocal(x,y);val raw=Point2(local.x.toDouble()+(rm?.originX?:0.0),local.y.toDouble()+(rm?.originY?:0.0));return if(snap)snapEndpoint(raw,(24f*resources.displayMetrics.density/scale).toDouble())?:raw else raw}

    private fun selectMeasurePoint(screenX:Float,screenY:Float){val raw=screenPoint(screenX,screenY,false);val snapped=snapEndpoint(raw,(24f*resources.displayMetrics.density/scale).toDouble());val point=snapped?:raw;val z=nearestPointZ(point)?:0.0;if(offsetMode){offsetBase=point;offsetBaseZ=z;onOffsetBaseSelected?.invoke(point,z,model?.units?:DrawingUnit.UNKNOWN,snapped!=null,suggestedOffsetDistance());invalidate();return};if(coordinateMode){coordinatePoint=point;coordinateZ=z;onCoordinateSelected?.invoke(point,coordinateZ,model?.units?:DrawingUnit.UNKNOWN,snapped!=null);invalidate();return};anySnapped=anySnapped||snapped!=null;if(areaMode){areaPoints+=point;notifyArea()}else if(measureStart==null){measureStart=point;onFirstMeasurePoint?.invoke()}else{val a=measureStart!!;val id=nextOverlayId++;overlays+=DistanceOverlay(id,a,point,activeMeasurementColor,distancePrimaryDefault,distanceSecondaryDefault);pendingDistanceId=id;selectedOverlayId=id;onMeasurement?.invoke(hypot(point.x-a.x,point.y-a.y),model?.units?:DrawingUnit.UNKNOWN,anySnapped);measureStart=null;measureEnd=null;emitOverlayState()};invalidate()}
    private fun suggestedOffsetDistance():Double{val raw=(min(width,height)*.16/scale).toDouble().coerceAtLeast(1.0);val magnitude=10.0.pow(floor(log10(raw)));val normalized=raw/magnitude;val step=when{normalized>=5.0->5.0;normalized>=2.0->2.0;else->1.0};return step*magnitude}
    private fun nearestPointZ(point:Point2):Double?=model?.primitives?.asSequence()?.filterIsInstance<Primitive.Point>()?.firstOrNull{abs(it.x-point.x)<1e-7&&abs(it.y-point.y)<1e-7}?.z
    private fun selectOverlayAt(x:Float,y:Float){val tolerance=24f*resources.displayMetrics.density;var selected:MeasurementOverlay?=null;var best=tolerance;for(overlay in overlays.asReversed()){val distance=when(overlay){is DistanceOverlay->distanceToSegment(x,y,screenX(overlay.a),screenY(overlay.a),screenX(overlay.b),screenY(overlay.b));is CoordinateOverlay->hypot((x-screenX(overlay.point)).toDouble(),(y-screenY(overlay.point)).toDouble()).toFloat();is AreaOverlay->{val screen=overlay.points.map{PointF(screenX(it),screenY(it))};if(screen.size>=3&&pointInPolygon(x,y,screen))0f else screen.indices.minOfOrNull{i->val a=screen[i];val b=screen[(i+1)%screen.size];distanceToSegment(x,y,a.x,a.y,b.x,b.y)}?:Float.MAX_VALUE}};if(distance<=best){best=distance;selected=overlay}};selectedOverlayId=selected?.id;emitOverlayState();invalidate()}
    private fun selectObjectAt(x:Float,y:Float){val rm=renderModel?:return;val tolerance=18f*resources.displayMetrics.density;var found:Primitive?=null;var best=tolerance;for(item in rm.geometry.asReversed()){val p=item.primitive;if(!isLayerVisible(p.layerId))continue;val distance=when(p){is Primitive.Line->{val a=screenPosition(Point2(p.x1,p.y1));val b=screenPosition(Point2(p.x2,p.y2));distanceToSegment(x,y,a.x,a.y,b.x,b.y)};is Primitive.Polyline->{var d=Float.MAX_VALUE;for(i in 2 until p.points.size step 2){val a=screenPosition(Point2(p.points[i-2],p.points[i-1]));val b=screenPosition(Point2(p.points[i],p.points[i+1]));d=min(d,distanceToSegment(x,y,a.x,a.y,b.x,b.y))};d};is Primitive.Circle->{val c=screenPosition(Point2(p.cx,p.cy));abs(hypot((x-c.x).toDouble(),(y-c.y).toDouble()).toFloat()-(p.radius*scale).toFloat())};is Primitive.Arc->{val c=screenPosition(Point2(p.cx,p.cy));abs(hypot((x-c.x).toDouble(),(y-c.y).toDouble()).toFloat()-(p.radius*scale).toFloat())};is Primitive.Point->{val s=screenPosition(Point2(p.x,p.y));hypot((x-s.x).toDouble(),(y-s.y).toDouble()).toFloat()};else->Float.MAX_VALUE};if(distance<=best){best=distance;found=p}};selectedObject=found;emitObjectSelection();invalidate()}
    private fun emitObjectSelection(){val p=selectedObject;onObjectSelectionChanged?.invoke(p?.let{primitive->val type=when(primitive){is Primitive.Line->"Линия (LINE)";is Primitive.Polyline->"Полилиния (LWPOLYLINE)";is Primitive.Circle->"Окружность (CIRCLE)";is Primitive.Arc->"Дуга (ARC)";is Primitive.Ellipse->"Эллипс (ELLIPSE)";is Primitive.Point->"Точка (POINT)";is Primitive.Face->"Грань (3DFACE)";is Primitive.Hatch->"Штриховка (HATCH)";is Primitive.Text->"Текст (TEXT)"};val length=when(primitive){is Primitive.Line->hypot(primitive.x2-primitive.x1,primitive.y2-primitive.y1);is Primitive.Polyline->{var sum=0.0;for(i in 2 until primitive.points.size step 2)sum+=hypot(primitive.points[i]-primitive.points[i-2],primitive.points[i+1]-primitive.points[i-1]);if(primitive.closed&&primitive.points.size>=4)sum+=hypot(primitive.points[0]-primitive.points[primitive.points.size-2],primitive.points[1]-primitive.points[primitive.points.size-1]);sum};is Primitive.Circle->2*PI*primitive.radius;is Primitive.Arc->abs(primitive.end-primitive.start)*primitive.radius;else->null};ObjectSelection(type,model?.layers?.firstOrNull{it.id==primitive.layerId}?.name?:"—",length,model?.units?:DrawingUnit.UNKNOWN,objectColorOverrides[primitive])})}
    private fun screenX(p:Point2):Float=screenPosition(p).x
    private fun screenY(p:Point2):Float=screenPosition(p).y
    private fun distanceToSegment(px:Float,py:Float,ax:Float,ay:Float,bx:Float,by:Float):Float{val dx=bx-ax;val dy=by-ay;val length=dx*dx+dy*dy;if(length<=1e-6f)return hypot((px-ax).toDouble(),(py-ay).toDouble()).toFloat();val t=(((px-ax)*dx+(py-ay)*dy)/length).coerceIn(0f,1f);return hypot((px-(ax+t*dx)).toDouble(),(py-(ay+t*dy)).toDouble()).toFloat()}
    private fun pointInPolygon(x:Float,y:Float,points:List<PointF>):Boolean{var inside=false;var j=points.lastIndex;for(i in points.indices){val a=points[i];val b=points[j];if((a.y>y)!=(b.y>y)&&x<(b.x-a.x)*(y-a.y)/(b.y-a.y)+a.x)inside=!inside;j=i};return inside}
    private fun notifyArea(){var twice=0.0;if(areaPoints.size>=3)for(i in areaPoints.indices){val a=areaPoints[i];val b=areaPoints[(i+1)%areaPoints.size];twice+=a.x*b.y-b.x*a.y};onAreaChanged?.invoke(abs(twice)/2,model?.units?:DrawingUnit.UNKNOWN,areaPoints.size)}
    private fun snapEndpoint(target:Point2,tolerance:Double):Point2?{val m=model?:return null;var best:Point2?=null;var bestD=tolerance*tolerance;fun candidate(x:Double,y:Double){val d=(x-target.x).pow(2)+(y-target.y).pow(2);if(d<=bestD){bestD=d;best=Point2(x,y)}};for(p in m.primitives){if(!isLayerVisible(p.layerId))continue;when(p){is Primitive.Line->{candidate(p.x1,p.y1);candidate(p.x2,p.y2)};is Primitive.Polyline->for(i in p.points.indices step 2)candidate(p.points[i],p.points[i+1]);is Primitive.Face->for(i in p.points.indices step 3)candidate(p.points[i],p.points[i+1]);is Primitive.Point->candidate(p.x,p.y);is Primitive.Arc->{candidate(p.cx+p.radius*cos(p.start),p.cy+p.radius*sin(p.start));candidate(p.cx+p.radius*cos(p.end),p.cy+p.radius*sin(p.end))};is Primitive.Ellipse->{fun ep(a:Double){val major=hypot(p.ax,p.ay);val angle=atan2(p.ay,p.ax);val lx=major*cos(a);val ly=major*p.ratio*sin(a);candidate(p.cx+lx*cos(angle)-ly*sin(angle),p.cy+lx*sin(angle)+ly*cos(angle))};ep(p.start);ep(p.end)};else->Unit}};return best}

    override fun onDraw(c:Canvas){
        val wallStart=System.nanoTime();val cpuStart=Debug.threadCpuTimeNanos();super.onDraw(c);c.drawColor(backgroundColor)
        val rm=renderModel?:return;if(fitPending){fit(rm.bounds);fitPending=false}
        val inv=1f/scale.coerceAtLeast(1e-5f);val corners=arrayOf(inverseLocal(0f,0f),inverseLocal(width.toFloat(),0f),inverseLocal(0f,height.toFloat()),inverseLocal(width.toFloat(),height.toFloat()))
        val vl=corners.minOf{it.x};val vr=corners.maxOf{it.x};val vb=corners.minOf{it.y};val vt=corners.maxOf{it.y}
        var geometryNs=0L;var textNs=0L;var hatchNs=0L;var visibleGeometry=0;var lodRejected=0;var culled=0;var hidden=0;var hatchSkipped=0;var hatchCandidates=0;var hatchVisible=0;var hatchDrawn=0;var hatchSegments=0;var hatchLod=0;var visibleTexts=0;val hatchBudget=HatchWorkBudget(MAX_HATCH_SEGMENTS_PER_FRAME)
        c.save();c.translate(tx,ty);c.rotate(rotationDegrees);c.scale(scale,-scale);paint.strokeWidth=1.2f*inv
        val gs=System.nanoTime()
        for(item in rm.geometry){
            val hatch=item.primitive as? Primitive.Hatch;if(hatch!=null)hatchCandidates++
            if(!isLayerVisible(item.primitive.layerId)){hidden++;continue}
            if(debugCulling&&!item.bounds.intersects(vl,vb,vr,vt)){culled++;continue}
            if(debugLod&&lodTooSmall(item)){lodRejected++;continue}
            if(!debugHatch&&hatch!=null){hatchSkipped++;continue}
            if(hatch!=null){val color=objectColorOverrides[hatch]?:resolvedLayerColor(hatch.layerId);paint.color=color;hatchPaint.color=color;hatchVisible++;val hs=System.nanoTime();val result=drawHatch(c,item,hatch,vl,vb,vr,vt,rm.originX,rm.originY,hatchBudget);hatchNs+=System.nanoTime()-hs;if(result.drawn)hatchDrawn++;hatchSegments+=result.segments;if(result.lodFallback)hatchLod++;if(hatch===selectedObject)drawObjectSelection(c,item,rm)}else drawCached(c,item,rm);visibleGeometry++
        }
        geometryNs=System.nanoTime()-gs;c.restore();val ts=System.nanoTime();visibleTexts=drawTexts(c,rm,vl,vb,vr,vt);textNs=System.nanoTime()-ts;drawMeasurement(c)
        val elapsed=System.nanoTime()-wallStart
        if(diagnosticFramePending){diagnosticFramePending=false;Log.i(TAG,"renderCounters scale=$scale total=${rm.geometry.size} drawn=$visibleGeometry hidden=$hidden culled=$culled lod=$lodRejected hatchCandidates=$hatchCandidates hatchVisible=$hatchVisible hatchDrawn=$hatchDrawn hatchSegmentsDrawn=$hatchSegments hatchLodFallback=$hatchLod hatchTimeMs=${hatchNs/1e6} hatchSkipped=$hatchSkipped flags=$debugLod/$debugCulling/$debugHatch")}
        profileFrame(wallStart,cpuStart,geometryNs,textNs,hatchNs,visibleGeometry,visibleTexts,lodRejected,rm);recordStress(elapsed,visibleGeometry,visibleTexts,lodRejected,hatchVisible,hatchDrawn,hatchSegments,hatchLod,hatchNs)
        if(firstRenderPending){firstRenderPending=false;val firstMs=elapsed/1e6;Log.i(TAG,"firstRenderMs=$firstMs primitives=${model?.primitives?.size} renderModelMs=${rm.buildMs} viewportLocal=[$vl,$vb,$vr,$vt] viewportWorld=[${vl+rm.originX},${vb+rm.originY},${vr+rm.originX},${vt+rm.originY}] scale=$scale tx=$tx ty=$ty");onFirstRender?.invoke(firstMs)}
    }

    private fun drawTexts(c:Canvas,rm:RenderModel,vl:Float,vb:Float,vr:Float,vt:Float):Int{var visible=0;for(item in rm.texts){val p=item.source;if((!textVisible&&p.hideable)||!isLayerVisible(p.layerId)||p.height<=0.0||(debugCulling&&!item.bounds.intersects(vl,vb,vr,vt)))continue;val capPixels=(p.height*scale).toFloat();if(debugLod&&capPixels<1.25f)continue;val size=capPixels/capHeightRatio;textPaint.color=resolvedLayerColor(p.layerId);textPaint.typeface=item.font.typeface;textPaint.textSize=size;textPaint.textScaleX=item.effectiveWidthFactor;val horizontal=if(p.multiline)(p.horizontal-1).mod(3)else p.horizontal;val anchor=screenPosition(Point2(p.x,p.y));c.save();c.translate(anchor.x,anchor.y);c.rotate(rotationDegrees-Math.toDegrees(p.rotation).toFloat());for(index in item.lines.indices){val width=item.unitWidths[index]*size*item.effectiveWidthFactor;val x=when(horizontal){1->-width/2;2->-width;else->0f};c.drawText(item.lines[index],x,item.baselines[index]*size,textPaint)};c.restore();visible++};textPaint.textScaleX=1f;return visible}
    private fun drawCached(c:Canvas,item:CachedGeometry,rm:RenderModel){val p=item.primitive;val color=objectColorOverrides[p]?:resolvedLayerColor(p.layerId);paint.color=color;solidPaint.color=color;when(p){is Primitive.Line->c.drawLine((p.x1-rm.originX).toFloat(),(p.y1-rm.originY).toFloat(),(p.x2-rm.originX).toFloat(),(p.y2-rm.originY).toFloat(),paint);is Primitive.Circle->c.drawCircle((p.cx-rm.originX).toFloat(),(p.cy-rm.originY).toFloat(),p.radius.toFloat(),paint);is Primitive.Arc->c.drawArc(item.oval!!,Math.toDegrees(p.start).toFloat(),Math.toDegrees(p.end-p.start).toFloat(),false,paint);is Primitive.Polyline->c.drawPath(item.path!!,paint);is Primitive.Face->c.drawPath(item.path!!,if(p.filled)solidPaint else paint);is Primitive.Point->drawPoint(c,p,rm);is Primitive.Ellipse->{c.save();c.rotate(Math.toDegrees(atan2(p.ay,p.ax)).toFloat(),(p.cx-rm.originX).toFloat(),(p.cy-rm.originY).toFloat());c.drawArc(item.oval!!,Math.toDegrees(p.start).toFloat(),Math.toDegrees(p.end-p.start).toFloat(),false,paint);c.restore()};is Primitive.Hatch,is Primitive.Text->Unit};if(p===selectedObject)drawObjectSelection(c,item,rm)}
    private fun drawObjectSelection(c:Canvas,item:CachedGeometry,rm:RenderModel){
        val p=item.primitive;objectSelectionPaint.strokeWidth=(4.5f/scale.coerceAtLeast(.001f)).coerceAtMost(1000f)
        when(p){
            is Primitive.Line->c.drawLine((p.x1-rm.originX).toFloat(),(p.y1-rm.originY).toFloat(),(p.x2-rm.originX).toFloat(),(p.y2-rm.originY).toFloat(),objectSelectionPaint)
            is Primitive.Circle->c.drawCircle((p.cx-rm.originX).toFloat(),(p.cy-rm.originY).toFloat(),p.radius.toFloat(),objectSelectionPaint)
            is Primitive.Arc->c.drawArc(item.oval!!,Math.toDegrees(p.start).toFloat(),Math.toDegrees(p.end-p.start).toFloat(),false,objectSelectionPaint)
            is Primitive.Polyline,is Primitive.Face,is Primitive.Hatch->item.path?.let{c.drawPath(it,objectSelectionPaint)}
            is Primitive.Point->{val x=(p.x-rm.originX).toFloat();val y=(p.y-rm.originY).toFloat();val r=7f/scale.coerceAtLeast(.001f);c.drawCircle(x,y,r,objectSelectionPaint)}
            is Primitive.Ellipse->{c.save();c.rotate(Math.toDegrees(atan2(p.ay,p.ax)).toFloat(),(p.cx-rm.originX).toFloat(),(p.cy-rm.originY).toFloat());c.drawArc(item.oval!!,Math.toDegrees(p.start).toFloat(),Math.toDegrees(p.end-p.start).toFloat(),false,objectSelectionPaint);c.restore()}
            is Primitive.Text->Unit
        }
    }
    private fun drawHatch(c:Canvas,item:CachedGeometry,p:Primitive.Hatch,vl:Float,vb:Float,vr:Float,vt:Float,originX:Double,originY:Double,budget:HatchWorkBudget):HatchDrawResult{if(!p.solid)return HatchDrawResult(false,0,true);val screenArea=abs((item.bounds.right-item.bounds.left)*(item.bounds.top-item.bounds.bottom))*scale*scale;val large=screenArea>width.toDouble()*height*.05;fun fallback():HatchDrawResult{return HatchDrawResult(false,0,true)};if(p.solid){if(large)return HatchDrawResult(false,0,true);c.drawPath(item.path!!,hatchPaint);return HatchDrawResult(true,0,false)};if(p.patternLines.isEmpty())return fallback();if((p.patternLines.minOfOrNull{hypot(it.ox,it.oy)*scale}?:Double.MAX_VALUE)<6.0)return fallback();val left=max(item.bounds.left,vl);val right=min(item.bounds.right,vr);val bottom=max(item.bounds.bottom,vb);val top=min(item.bounds.top,vt);if(right<=left||top<=bottom)return HatchDrawResult(false,0,false);val diagonal=hypot((right-left).toDouble(),(top-bottom).toDouble()).toFloat().coerceAtLeast(1f);val centerX=(left+right)/2;val centerY=(bottom+top)/2;var required=0;for(line in p.patternLines){val step=hypot(line.ox,line.oy).coerceAtLeast(1e-9);required+=2*(ceil(diagonal/step).toInt()+2)+1;if(required>budget.remainingSegments)return fallback()};hatchPatternPath.rewind();var segments=0;for(line in p.patternLines){val dl=hypot(line.dx,line.dy).coerceAtLeast(1e-9);val ux=(line.dx/dl).toFloat();val uy=(line.dy/dl).toFloat();val step2=line.ox*line.ox+line.oy*line.oy;val baseX=line.px-originX;val baseY=line.py-originY;val centerK=if(step2>1e-18)round(((centerX-baseX)*line.ox+(centerY-baseY)*line.oy)/step2).toInt()else 0;val count=ceil(diagonal/sqrt(step2.coerceAtLeast(1e-18))).toInt()+2;for(offset in -count..count){val k=centerK+offset;val cx=(baseX+k*line.ox).toFloat();val cy=(baseY+k*line.oy).toFloat();hatchPatternPath.moveTo(cx-ux*diagonal*2,cy-uy*diagonal*2);hatchPatternPath.lineTo(cx+ux*diagonal*2,cy+uy*diagonal*2);segments++}};budget.remainingSegments-=segments;c.save();c.clipPath(item.path!!);c.clipRect(left,bottom,right,top);c.drawPath(hatchPatternPath,paint);c.restore();return HatchDrawResult(true,segments,false)}
    private fun drawPoint(c:Canvas,p:Primitive.Point,rm:RenderModel){val x=(p.x-rm.originX).toFloat();val y=(p.y-rm.originY).toFloat();val r=(if(p.size>0)p.size.toFloat() else 6f/scale).coerceAtLeast(2f/scale);when(p.mode and 7){0->c.drawCircle(x,y,1.5f/scale,paint);2->{c.drawLine(x-r,y,x+r,y,paint);c.drawLine(x,y-r,x,y+r,paint)};3->{c.drawLine(x-r,y-r,x+r,y+r,paint);c.drawLine(x-r,y+r,x+r,y-r,paint)};4->c.drawLine(x,y-r,x,y+r,paint)};if(p.mode and 32!=0)c.drawCircle(x,y,r,paint);if(p.mode and 64!=0)c.drawRect(x-r,y-r,x+r,y+r,paint)}
    private fun drawMeasurement(c:Canvas){renderModel?:return;for(overlay in overlays){val selected=overlay.id==selectedOverlayId;when(overlay){is DistanceOverlay->drawDistance(c,overlay.a,overlay.b,overlay.color,selected,overlayDisplayLabel(overlay));is AreaOverlay->drawArea(c,overlay.points,overlay.color,selected,selected,overlayDisplayLabel(overlay));is CoordinateOverlay->drawCoordinate(c,overlay.point,overlay.color,selected)}};coordinatePoint?.let{drawCoordinate(c,it,measurementAccentColor,false)};offsetBase?.let{drawCoordinate(c,it,measurementAccentColor,false)};val preview=offsetPreview;val base=offsetBase;if(preview!=null&&base!=null){val x1=screenX(base);val y1=screenY(base);val x2=screenX(preview);val y2=screenY(preview);c.drawLine(x1,y1,x2,y2,offsetPreviewPaint);offsetPreviewPaint.style=Paint.Style.FILL;c.drawCircle(x2,y2,10f,offsetPreviewPaint);offsetPreviewPaint.style=Paint.Style.STROKE};if(areaMode&&areaPoints.isNotEmpty()){drawArea(c,areaPoints,activeMeasurementColor,true,false,null);return};measureStart?.let{a->drawCoordinate(c,a,activeMeasurementColor,false);measureEnd?.let{drawDistance(c,a,it,activeMeasurementColor,false,null)}}}
    private fun drawCoordinate(c:Canvas,p:Point2,color:Int,selected:Boolean){val x=screenX(p);val y=screenY(p);val radius=if(selected)13f else 10f;measurePaint.color=color;measurePaint.strokeWidth=if(selected)5f else 3f;c.drawLine(x-radius,y,x+radius,y,measurePaint);c.drawLine(x,y-radius,x,y+radius,measurePaint);c.drawCircle(x,y,if(selected)6f else 4f,measurePaint)}
    private fun drawDistance(c:Canvas,a:Point2,b:Point2,color:Int,selected:Boolean,label:String?){val ax=screenX(a);val ay=screenY(a);val bx=screenX(b);val by=screenY(b);measurePaint.color=color;measurePaint.strokeWidth=if(selected)5f else 3f;c.drawLine(ax,ay,bx,by,measurePaint);c.drawCircle(ax,ay,if(selected)10f else 7f,measurePaint);c.drawCircle(bx,by,if(selected)10f else 7f,measurePaint);label?.let{drawMeasurementLabel(c,it,(ax+bx)/2,(ay+by)/2-10f,color)}}
    private fun drawArea(c:Canvas,points:List<Point2>,color:Int,editable:Boolean,selected:Boolean,label:String?){if(points.isEmpty())return;val path=Path();var cx=0f;var cy=0f;points.forEachIndexed{i,p->val x=screenX(p);val y=screenY(p);if(i==0)path.moveTo(x,y)else path.lineTo(x,y);cx+=x;cy+=y};if(points.size>=3)path.close();measurePaint.color=color;measurePaint.alpha=255;measurePaint.style=Paint.Style.STROKE;measurePaint.strokeWidth=if(selected)5f else 3f;if(points.size>=3){measurementFillPaint.color=color;measurementFillPaint.alpha=35;c.drawPath(path,measurementFillPaint)};c.drawPath(path,measurePaint);if(editable)points.forEachIndexed{i,p->c.drawCircle(screenX(p),screenY(p),if(i==areaDragIndex||selected)11f else 7f,measurePaint)};if(!editable&&points.size>=3)label?.let{drawMeasurementLabel(c,it,cx/points.size,cy/points.size,color)}}
    private fun drawMeasurementLabel(c:Canvas,label:String,x:Float,y:Float,color:Int){if(label.isBlank())return;measurementTextPaint.textSize=(measurementTextSizeSp*resources.displayMetrics.scaledDensity).coerceAtLeast(12f);measurementTextPaint.color=color;val fm=measurementTextPaint.fontMetrics;val padding=6f*resources.displayMetrics.density;val width=measurementTextPaint.measureText(label);val half=width/2f;val labelX=if(width+padding*2<c.width)x.coerceIn(half+padding,c.width-half-padding)else c.width/2f;measurementLabelBackgroundPaint.color=if((Color.red(backgroundColor)+Color.green(backgroundColor)+Color.blue(backgroundColor))/3<128)Color.argb(190,5,10,14)else Color.argb(190,255,255,255);val rect=RectF(labelX-half-padding,y+fm.ascent-padding,labelX+half+padding,y+fm.descent+padding);c.drawRoundRect(rect,8f,8f,measurementLabelBackgroundPaint);c.drawText(label,labelX,y,measurementTextPaint)}
    private fun areaLabel(points:List<Point2>):String{var twice=0.0;for(i in points.indices){val a=points[i];val b=points[(i+1)%points.size];twice+=a.x*b.y-b.x*a.y};val area=abs(twice)/2;val factor=when(model?.units){DrawingUnit.MILLIMETERS->1.0;DrawingUnit.CENTIMETERS->10.0;DrawingUnit.METERS->1000.0;else->null};if(factor==null)return "${formatMeasurement(area,true)} кв. ед.";val mm2=area*factor*factor;return "${formatMeasurement(mm2,false)} мм² · ${formatMeasurement(mm2/1_000_000,true)} м²"}
    private fun distanceLabel(a:Point2,b:Point2):String{val distance=hypot(b.x-a.x,b.y-a.y);val factor=when(model?.units){DrawingUnit.MILLIMETERS->1.0;DrawingUnit.CENTIMETERS->10.0;DrawingUnit.METERS->1000.0;else->null};if(factor==null)return "${formatMeasurement(distance,true)} ед.";val mm=distance*factor;return "${formatMeasurement(mm,false)} мм · ${formatMeasurement(mm/1000,true)} м"}
    private fun overlayParts(overlay:MeasurementOverlay):Pair<String,String?>{val label=when(overlay){is DistanceOverlay->distanceLabel(overlay.a,overlay.b);is AreaOverlay->areaLabel(overlay.points);is CoordinateOverlay->"X ${formatMeasurement(overlay.point.x,true)} · Y ${formatMeasurement(overlay.point.y,true)}"+(overlay.z?.let{" · Z ${formatMeasurement(it,true)}"}?:"")};val parts=label.split(" · ",limit=2);return parts[0] to parts.getOrNull(1)}
    private fun overlayDisplayLabel(overlay:MeasurementOverlay):String{val parts=overlayParts(overlay);return listOfNotNull(parts.first.takeIf{overlay.primaryVisible},parts.second?.takeIf{overlay.secondaryVisible}).joinToString(" · ")}
    private fun resolvedLayerColor(layerId:Int):Int{if(!useLayerColors)return foregroundColor;val raw=layerColorOverrides.getOrElse(layerId){-1}.takeIf{it>=0}?:model?.layers?.getOrNull(layerId)?.dwgColor?:foregroundColor;val r=Color.red(raw);val g=Color.green(raw);val b=Color.blue(raw);val br=Color.red(backgroundColor);val bg=Color.green(backgroundColor);val bb=Color.blue(backgroundColor);val distance=abs(r-br)+abs(g-bg)+abs(b-bb);return if(distance<150){if((br+bg+bb)/3<128)Color.rgb(max(r,180),max(g,180),max(b,180))else Color.rgb(min(r,70),min(g,70),min(b,70))}else Color.rgb(r,g,b)}
    private fun emitOverlayState(){val selected=selectedOverlayId?.let{id->overlays.firstOrNull{it.id==id}};onOverlayStateChanged?.invoke(overlays.size,selected?.let{val parts=overlayParts(it);OverlaySelection(parts.first,parts.second,it.primaryVisible,it.secondaryVisible)})}
    private fun formatMeasurement(value:Double,fixed:Boolean):String=(if(fixed)fixedMeasurementFormat else flexibleMeasurementFormat).format(value)

    private fun buildRenderModel(m:DrawingModel):RenderModel{val started=System.nanoTime();val origin=renderOrigin(m);val ox=origin.first;val oy=origin.second;val geometry=ArrayList<CachedGeometry>(m.primitives.size);val texts=ArrayList<TextLayoutModel>();var reportedTexts=0;var all:Bounds?=null;fun merge(b:Bounds){val a=all;all=if(a==null)b else Bounds(min(a.left,b.left),min(a.bottom,b.bottom),max(a.right,b.right),max(a.top,b.top))};val capRatio=capHeightRatio;val layoutPaint=Paint(Paint.ANTI_ALIAS_FLAG).apply{textSize=1f;typeface=Typeface.SANS_SERIF};val fontMetrics=HashMap<Typeface,UnitFontMetrics>(4);for(p in m.primitives){if(Thread.currentThread().isInterrupted)throw CancellationException();when(p){is Primitive.Text->{val font=FontResolver.resolve(p);layoutPaint.typeface=font.typeface;val fm=fontMetrics.getOrPut(font.typeface){layoutPaint.fontMetrics.let{UnitFontMetrics(it.ascent,it.descent)}};val effective=(p.widthFactor*p.styleWidthFactor).toFloat().coerceIn(.1f,10f);val decoded=if(p.multiline)MTextDecoder.decode(p.value)else DecodedMText(if(p.value.contains("%%d",true))p.value.replace("%%d","°",true)else p.value,emptySet());val lines=layoutText(decoded.plainText,p,capRatio,effective,layoutPaint);val widths=FloatArray(lines.size){layoutPaint.measureText(lines[it])};val advance=(5f/3f)*p.lineSpacing.toFloat()*capRatio;val block=(lines.size-1).coerceAtLeast(0)*advance+(fm.descent-fm.ascent);val vertical=if(p.multiline)(p.horizontal-1)/3 else p.vertical;val first=if(p.multiline)when(vertical){0->-fm.ascent;1->-fm.ascent-block/2;else->-fm.ascent-block}else when(p.vertical){1->-fm.descent;2->-(fm.ascent+fm.descent)/2;3->-fm.ascent;else->0f};val baselines=FloatArray(lines.size){first+it*advance};val width=max(p.boxWidth,if(widths.isEmpty())0.0 else widths.max().toDouble()*p.height*effective/capRatio);val blockHeight=p.height*((lines.size-1).coerceAtLeast(0)*(5.0/3.0)*p.lineSpacing+1.0);val radius=hypot(width,blockHeight).coerceAtLeast(p.height);val b=Bounds((p.x-ox-radius).toFloat(),(p.y-oy-radius).toFloat(),(p.x-ox+radius).toFloat(),(p.y-oy+radius).toFloat());texts+=TextLayoutModel(p,lines,widths,baselines,b,font,effective);merge(b);if(p.multiline&&reportedTexts++<12)Log.i(TAG,"textDebug raw=${p.value.take(240)} decoded=${decoded.plainText.take(240)} lines=${lines.contentToString()} style=${p.styleName} font=${font.source} shx=${font.shx} height=${p.height} widthFactor=$effective rotation=${p.rotation} attachment=${p.horizontal} boxWidth=${p.boxWidth} anchor=${p.x},${p.y} bounds=$b");if(decoded.unsupportedCommands.isNotEmpty())Log.w(TAG,"mtextUnsupported=${decoded.unsupportedCommands} raw=${p.value.take(160)} decoded=${decoded.plainText.take(160)}")};else->{val cached=cacheGeometry(p,ox,oy);geometry+=cached;merge(cached.bounds)}}};val bounds=all?:Bounds(0f,0f,1f,1f);val ms=(System.nanoTime()-started)/1e6;Log.i(TAG,"renderModelMs=$ms geometry=${geometry.size} texts=${texts.size} origin=$ox,$oy localBounds=$bounds maxAbsWorld=${max(abs(ox),abs(oy))}");return RenderModel(geometry,texts,bounds,ox,oy,ms)}
    private fun renderOrigin(m:DrawingModel):Pair<Double,Double>{for(p in m.primitives){val v=when(p){is Primitive.Line->p.x1 to p.y1;is Primitive.Circle->p.cx to p.cy;is Primitive.Arc->p.cx to p.cy;is Primitive.Polyline->if(p.points.size>=2)p.points[0] to p.points[1] else null;is Primitive.Face->if(p.points.size>=3)p.points[0] to p.points[1] else null;is Primitive.Ellipse->p.cx to p.cy;is Primitive.Point->p.x to p.y;is Primitive.Hatch->p.contours.firstOrNull{it.size>=2}?.let{it[0] to it[1]};is Primitive.Text->p.x to p.y};if(v!=null&&v.first.isFinite()&&v.second.isFinite())return v};return 0.0 to 0.0}
    private fun layoutText(text:String,p:Primitive.Text,capRatio:Float,effectiveWidth:Float,layoutPaint:Paint):Array<String>{val paragraphs=text.split('\n');if(!p.multiline||p.boxWidth<=0.0)return paragraphs.toTypedArray();val maxUnit=(p.boxWidth*capRatio/(p.height*effectiveWidth)).toFloat();val result=ArrayList<String>();for(paragraph in paragraphs){if(paragraph.isEmpty()){result+="";continue};var line="";for(word in paragraph.split(WORD_SEPARATOR)){val candidate=if(line.isEmpty())word else "$line $word";if(line.isNotEmpty()&&layoutPaint.measureText(candidate)>maxUnit){result+=line;line=word}else line=candidate};result+=line};return result.toTypedArray()}
    private fun cacheGeometry(p:Primitive,ox:Double,oy:Double):CachedGeometry=when(p){is Primitive.Line->{val b=Bounds((min(p.x1,p.x2)-ox).toFloat(),(min(p.y1,p.y2)-oy).toFloat(),(max(p.x1,p.x2)-ox).toFloat(),(max(p.y1,p.y2)-oy).toFloat());CachedGeometry(p,b)};is Primitive.Circle->{val b=Bounds((p.cx-ox-p.radius).toFloat(),(p.cy-oy-p.radius).toFloat(),(p.cx-ox+p.radius).toFloat(),(p.cy-oy+p.radius).toFloat());CachedGeometry(p,b)};is Primitive.Arc->{val r=RectF((p.cx-ox-p.radius).toFloat(),(p.cy-oy-p.radius).toFloat(),(p.cx-ox+p.radius).toFloat(),(p.cy-oy+p.radius).toFloat());CachedGeometry(p,Bounds(r.left,r.top,r.right,r.bottom),oval=r)};is Primitive.Polyline->{val path=Path();var minX=Float.POSITIVE_INFINITY;var minY=minX;var maxX=Float.NEGATIVE_INFINITY;var maxY=maxX;if(p.points.size>=2){path.moveTo((p.points[0]-ox).toFloat(),(p.points[1]-oy).toFloat());for(i in p.points.indices step 2){val x=(p.points[i]-ox).toFloat();val y=(p.points[i+1]-oy).toFloat();if(i>0)path.lineTo(x,y);minX=min(minX,x);minY=min(minY,y);maxX=max(maxX,x);maxY=max(maxY,y)};if(p.closed)path.close()};CachedGeometry(p,Bounds(minX,minY,maxX,maxY),path=path)};is Primitive.Face->cacheFace(p,ox,oy);is Primitive.Ellipse->{val major=hypot(p.ax,p.ay);val cx=p.cx-ox;val cy=p.cy-oy;val r=RectF((cx-major).toFloat(),(cy-major*p.ratio).toFloat(),(cx+major).toFloat(),(cy+major*p.ratio).toFloat());CachedGeometry(p,Bounds((cx-major).toFloat(),(cy-major).toFloat(),(cx+major).toFloat(),(cy+major).toFloat()),oval=r)};is Primitive.Point->{val x=(p.x-ox).toFloat();val y=(p.y-oy).toFloat();val r=if(p.size>0)p.size.toFloat() else 0f;CachedGeometry(p,Bounds(x-r,y-r,x+r,y+r))};is Primitive.Hatch->cacheHatch(p,ox,oy);is Primitive.Text->error("Text cached separately")}
    private fun cacheFace(p:Primitive.Face,ox:Double,oy:Double):CachedGeometry{val path=Path();var minX=Float.POSITIVE_INFINITY;var minY=minX;var maxX=Float.NEGATIVE_INFINITY;var maxY=maxX;for(i in p.points.indices step 3){val x=(p.points[i]-ox).toFloat();val y=(p.points[i+1]-oy).toFloat();if(i==0)path.moveTo(x,y)else path.lineTo(x,y);minX=min(minX,x);minY=min(minY,y);maxX=max(maxX,x);maxY=max(maxY,y)};path.close();return CachedGeometry(p,Bounds(minX,minY,maxX,maxY),path=path)}
    private fun cacheHatch(p:Primitive.Hatch,ox:Double,oy:Double):CachedGeometry{val boundary=Path().apply{fillType=Path.FillType.EVEN_ODD};var minX=Float.POSITIVE_INFINITY;var minY=minX;var maxX=Float.NEGATIVE_INFINITY;var maxY=maxX;for(points in p.contours)if(points.size>=6){boundary.moveTo((points[0]-ox).toFloat(),(points[1]-oy).toFloat());for(i in 2 until points.size step 2){val x=(points[i]-ox).toFloat();val y=(points[i+1]-oy).toFloat();boundary.lineTo(x,y)};boundary.close();for(i in points.indices step 2){val x=(points[i]-ox).toFloat();val y=(points[i+1]-oy).toFloat();minX=min(minX,x);minY=min(minY,y);maxX=max(maxX,x);maxY=max(maxY,y)}};return CachedGeometry(p,Bounds(minX,minY,maxX,maxY),path=boundary)}
    private fun fit(b:Bounds){if(b.right>b.left&&b.top>b.bottom){scale=min((width-40)/(b.right-b.left),(height-40)/(b.top-b.bottom)).coerceAtLeast(1e-5f);tx=(width-(b.left+b.right)*scale)/2;ty=(height+(b.bottom+b.top)*scale)/2}}
    private val stressStep=object:Runnable{override fun run(){val frame=stressFrame;if(frame !in 0 until 180){stressFrame=-1;Log.i(TAG,"stressProfile complete");return};if(frame==0)fitPending=true;if(frame==60||frame==120){val factor=4f;tx=width/2-(width/2-tx)*factor;ty=height/2-(height/2-ty)*factor;scale=(scale*factor).coerceIn(MIN_SCALE,MAX_SCALE)}else if(frame%60!=0){tx+=sin(frame*.23).toFloat()*3f;ty+=cos(frame*.19).toFloat()*2f};stressFrame=frame+1;invalidate();postOnAnimation(this)}}
    private fun recordStress(elapsed:Long,visibleGeometry:Int,visibleTexts:Int,lodRejected:Int,hatchVisible:Int,hatchDrawn:Int,hatchSegments:Int,hatchLod:Int,hatchNs:Long){val frame=stressFrame-1;if(frame !in 0 until 180)return;val local=frame%60;stressTimes[local]=elapsed;if(local==59){val sorted=stressTimes.clone().apply{sort()};val name=arrayOf("fit","medium","close")[frame/60];Log.i(TAG,"stressProfile scenario=$name avgMs=%.2f p95Ms=%.2f p99Ms=%.2f fps=%.1f visibleGeometry=%d visibleTexts=%d lodRejected=%d hatchVisible=%d hatchDrawn=%d hatchSegments=%d hatchLod=%d hatchTimeMs=%.2f pssKb=%d".format(stressTimes.average()/1e6,sorted[57]/1e6,sorted[59]/1e6,1000.0/(stressTimes.average()/1e6),visibleGeometry,visibleTexts,lodRejected,hatchVisible,hatchDrawn,hatchSegments,hatchLod,hatchNs/1e6,Debug.getPss()))}}
    private fun profileFrame(start:Long,cpuStart:Long,geometryNs:Long,textNs:Long,hatchNs:Long,visibleGeometry:Int,visibleTexts:Int,lodRejected:Int,rm:RenderModel){val elapsed=System.nanoTime()-start;frameTimes[frameIndex++%frameTimes.size]=elapsed;frameCount++;val now=SystemClock.uptimeMillis();if(frameCount<frameTimes.size||now-lastProfileMs<2000)return;lastProfileMs=now;val sorted=frameTimes.clone().apply{sort()};val average=frameTimes.average()/1e6;val p95=sorted[(sorted.size*.95).toInt().coerceAtMost(sorted.lastIndex)]/1e6;val p99=sorted[(sorted.size*.99).toInt().coerceAtMost(sorted.lastIndex)]/1e6;val gc=runtimeStat("art.gc.gc-count");Log.i(TAG,"frameProfile avgMs=%.2f p95Ms=%.2f p99Ms=%.2f fps=%.1f onDrawMs=%.2f geometryMs=%.2f textMs=%.2f hatchTimeMs=%.2f cpuMs=%.2f visibleGeometry=%d visibleTexts=%d lodRejected=%d totalGeometry=%d totalTexts=%d gcDelta=%d pssKb=%d".format(average,p95,p99,1000.0/average,elapsed/1e6,geometryNs/1e6,textNs/1e6,hatchNs/1e6,(Debug.threadCpuTimeNanos()-cpuStart)/1e6,visibleGeometry,visibleTexts,lodRejected,rm.geometry.size,rm.texts.size,gc-lastGcCount,Debug.getPss()));lastGcCount=gc}
    private fun runtimeStat(name:String)=Debug.getRuntimeStat(name)?.toLongOrNull()?:0L
    companion object{private const val TAG="BraginCADRender";private const val MIN_SCALE=1e-5f;private const val MAX_SCALE=1e5f;private const val ROTATION_SLOP_DEGREES=4f;private const val ZOOM_INTENT_SLOP=.025f;private const val MAX_HATCH_SEGMENTS_PER_FRAME=12_000;private val WORD_SEPARATOR=Regex("[ \\t]+");private val RENDER_EXECUTOR=Executors.newSingleThreadExecutor{r->Thread(r,"dwg-render-model").apply{isDaemon=true}};private fun measurementFormat(decimals:Int,fixed:Boolean)=NumberFormat.getNumberInstance(Locale.forLanguageTag("ru-RU")).apply{maximumFractionDigits=decimals;minimumFractionDigits=if(fixed)decimals else 0;isGroupingUsed=true};private val AREA_COLORS=intArrayOf(Color.rgb(0,150,199),Color.rgb(239,108,0),Color.rgb(123,31,162),Color.rgb(46,125,50))}
}
